import{renderDiagram}from './visual.js?v=20261023-physicscomplete01';import{physicsFigure}from './phy1-figures.js?v=20261023-physicscomplete01';export function showPhy1(spec='stores',w={}){let[kind,card]=spec.split(':');if(card==='2'&&kind==='kinetic'||card==='1'&&kind==='elastic')kind+='-model';renderDiagram(w.title||'Explore energy changes',w.label||'Original educational model',physicsFigure({kind,state:card||'0',...w}),'PHYSICS · ENERGY');}
